def output_tokens(response: dict) -> int:
    """How many tokens the model produced, as reported in usage."""
    return response["usage"]["output_tokens"]

def describe(response: dict):
    print(output_tokens(response), "tokens")

result = describe({"usage": {"output_tokens": 31}})  # prints, then result is None

def reply_text(response: dict) -> str:
    """Join the text blocks of a Messages-style response."""
    parts = []
    for block in response["content"]:
        if block.get("type") == "text":
            parts.append(block["text"])
    return "".join(parts)

