def build_request(*, system, user_text, schema):
    output_config = {"format": {"type": "json_schema", "schema": schema}}
    return {"model": config.model(), "max_tokens": config.max_tokens(),
            "system": system,
            "messages": [{"role": "user", "content": user_text}],
            "output_config": output_config}

class PracticeQuestion(BaseModel):
    question: str = Field(min_length=1, max_length=1000)
    question_type: Literal["multiple_choice", "short_answer"]
    options: list[str] = Field(max_length=4)
    expected_answer: str = Field(min_length=1, max_length=1500)
    section_refs: list[int] = Field(min_length=1, max_length=8)

    @model_validator(mode="after")
    def valid_key(self):
        if self.question_type == "multiple_choice":
            if (len(self.options) != 4 or len(set(self.options)) != 4
                    or self.expected_answer not in self.options):
                raise ValueError("Multiple-choice key must match one of four distinct options")
        elif self.options:
            raise ValueError("Short-answer questions must have no options")
        return self

