MAX_STEPS = 6
ALLOWED = {"search_library": search_library}

def run_agent(goal, call_model):
    messages = [{"role": "user", "content": goal}]
    for step in range(MAX_STEPS):
        reply = call_model(messages)
        messages.append({"role": "assistant", "content": reply.content})
        if reply.stop_reason != "tool_use":
            return reply  # a final answer
        results = []
        for call in tool_calls(reply):
            tool = ALLOWED.get(call.name)
            if tool is None or not valid_input(call):
                output, is_error = "Tool not available or input invalid.", True
            else:
                output, is_error = tool(**call.input), False
            results.append({"type": "tool_result", "tool_use_id": call.id,
                            "content": output, "is_error": is_error})
        messages.append({"role": "user", "content": results})
    raise RuntimeError("Stopped: step limit reached without a final answer")
